mapper.select:
select content from homework.passtask

     and content = #{content}
    and subject = #{subject}
    and class_number = #{classNumber}
    and type = #{type}

select * from homework.recordtask


        and content like concat('%',#{content},'%')


        and class_number = #{classNumber}


        and subject = #{subject}


        and checkdate between #{startdate} and #{enddate}


        and name like concat('%',#{name},'%')


        AND completed = #{completed}
